INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('nfhj804','남극해 관련 국제사회에서 해양외교 노력 결실! 국제규범 제안 채택에 이어 새 어장 개척도 성공','우리나라가 제안한 2건의 국제규범이 남극해양생물자원보존위원회(CCAMLR) 연례 회의에서 채택되었다. 또한 우리측의 과학 조사를 근거로 남극해 ''88.3 해구''의 새 어장이 개척되어 이빨고기 조업 재개의 길이 열렸다.','우리나라가 제안한 2건의 국제규범이 남극해양생물자원보존위원회(CCAMLR) 연례 회의에서 채택되었다. 또한 우리측의 과학 조사를 근거로 남극해 ''88.3 해구''의 새 어장이 개척되어 이빨고기 조업 재개의 길이 열렸다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787891','2026-11-04',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('ngncedd','(동정) 남재헌 해수부 차관, 부산국제수산엑스포에서 수산식품 수출 현장 점검','남재헌 해양수산부 차관이 ''제24회 부산국제수산엑스포'' 개막식에 참석하고 해외 바이어 초청 수산식품 수출 무역상담회를 점검했다. 남 차관은 수출 기업들을 격려하며 고부가가치 상품 개발과 해외 시장 개척 등을 통해 수산식품 수출을 든든히 뒷받침하겠다고 밝혔다.','남재헌 해양수산부 차관이 ''제24회 부산국제수산엑스포'' 개막식에 참석하고 해외 바이어 초청 수산식품 수출 무역상담회를 점검했다. 남 차관은 수출 기업들을 격려하며 고부가가치 상품 개발과 해외 시장 개척 등을 통해 수산식품 수출을 든든히 뒷받침하겠다고 밝혔다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787964','2026-11-04',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('ni0wvjd','해수부-경제협력개발기구-한국해양수산개발원, 세계해양포럼에서 해양경제를 논한다','해양수산부는 OECD 및 한국해양수산개발원과 함께 부산에서 세계와 한국의 해양경제를 주제로 국제 세미나를 개최한다. 이번 행사에서 국내 해양수산업의 총산출액은 약 197.7조 원, 부가가치는 약 63.2조 원 등으로 발표되었다.','해양수산부는 OECD 및 한국해양수산개발원과 함께 부산에서 세계와 한국의 해양경제를 주제로 국제 세미나를 개최한다. 이번 행사에서 국내 해양수산업의 총산출액은 약 197.7조 원, 부가가치는 약 63.2조 원 등으로 발표되었다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787890','2026-11-04',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('nwmk9yy','세계 해양의 혁신 기술, ''오션테크코리아''에서 국내 기업과 연결된다','해양수산부는 해외 혁신기업의 기술과 사업 모델을 소개하고 국내 기업과의 비즈니스 미팅을 지원하는 ''오션테크코리아''를 개최한다. 이번 행사를 통해 국내 해양수산기업들이 세계 시장을 선제적으로 개척하고 수출 성과를 창출할 수 있도록 도울 예정이다.','해양수산부는 해외 혁신기업의 기술과 사업 모델을 소개하고 국내 기업과의 비즈니스 미팅을 지원하는 ''오션테크코리아''를 개최한다. 이번 행사를 통해 국내 해양수산기업들이 세계 시장을 선제적으로 개척하고 수출 성과를 창출할 수 있도록 도울 예정이다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787892','2026-11-04',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('n92avpz','수과원, 개체굴 선진 양식기술서 국문판 발간','국립수산과학원은 개체굴 양식기술의 국내 확산과 산업 경쟁력 강화를 위해 국제 선진 양식기술을 담은 「개체굴 양식기술 기초지식」 국문판을 발간했다. 이 책자는 종자생산부터 양성시설 및 관리 등 실용 기술을 담았으며, 관련 워크숍에서 처음 공개되어 무료로 배포될 예정이다.','국립수산과학원은 개체굴 양식기술의 국내 확산과 산업 경쟁력 강화를 위해 국제 선진 양식기술을 담은 「개체굴 양식기술 기초지식」 국문판을 발간했다. 이 책자는 종자생산부터 양성시설 및 관리 등 실용 기술을 담았으며, 관련 워크숍에서 처음 공개되어 무료로 배포될 예정이다.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4927&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-03',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('nvgsq2d','수과원, 서해 먼바다 멸치 어장 이용 가능성 확인','국립수산과학원은 서해 황해저층냉수해역에서 멸치 어군이 강하게 형성되어 새로운 어장으로 이용될 가능성이 높다고 밝혔다. 융합탐지기술을 통한 조사 결과, 저층냉수대역 주변에서 멸치의 어획 비중과 어군 밀도가 크게 증가한 것으로 확인됐다.','국립수산과학원은 서해 황해저층냉수해역에서 멸치 어군이 강하게 형성되어 새로운 어장으로 이용될 가능성이 높다고 밝혔다. 융합탐지기술을 통한 조사 결과, 저층냉수대역 주변에서 멸치의 어획 비중과 어군 밀도가 크게 증가한 것으로 확인됐다.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4929&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-03',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('n_ko_156782514','고수온 피해 양식 어가에 1차 재난 지원금','해양수산부는 추석 명절 전 고수온 피해를 입은 338개 어가를 대상으로 재난 지원금 137억 원을 신속히 지원한다. 아울러 피해 어가를 위한 대출 상환 연기 및 이자 감면 등 간접 지원도 함께 추진한다.','해양수산부는 추석 명절 전 고수온 피해를 입은 338개 어가를 대상으로 재난 지원금 137억 원을 신속히 지원한다. 아울러 피해 어가를 위한 대출 상환 연기 및 이자 감면 등 간접 지원도 함께 추진한다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156782514','2026-09-20',1,1,'2026-11-11T00:00:00+09:00');
INSERT OR IGNORE INTO news (id,title,summary,body,source,url,date,ai,public,created_at) VALUES ('n_ko_148965977','한국의 갯벌, 세계유산 확대 등재 권고','국제자연보전연맹은 한국의 갯벌 세계유산 범위를 여수·고흥·무안·서산 갯벌까지 확대할 것을 권고했습니다. 2026년 6월 발표 당시 최종 결정은 세계유산위원회에 예정돼 있었습니다. 원문의 텍스트는 공공누리 제1유형입니다.','국제자연보전연맹은 한국의 갯벌 세계유산 범위를 여수·고흥·무안·서산 갯벌까지 확대할 것을 권고했습니다. 2026년 6월 발표 당시 최종 결정은 세계유산위원회에 예정돼 있었습니다. 원문의 텍스트는 공공누리 제1유형입니다.','국가유산청·해양수산부 / 정책브리핑','https://www.korea.kr/news/policyNewsView.do?newsId=148965977','2026-06-05',0,1,'2026-11-11T00:00:00+09:00');
INSERT INTO quizquestion (q,options,answer,explain,active) SELECT '고래는 물속에서 계속 숨을 쉴 수 있을까요?','["네, 아가미로 숨 쉬어요", "아니요, 물 위로 올라와 숨 쉬어요", "산호에서 산소를 얻어요", "먹이에서 산소를 얻어요"]',1,'고래는 포유류라 공기를 마셔요. 물 위로 올라와 머리 위 숨구멍으로 숨을 쉬어요.',1 WHERE NOT EXISTS (SELECT 1 FROM quizquestion WHERE q='고래는 물속에서 계속 숨을 쉴 수 있을까요?');
INSERT INTO quizquestion (q,options,answer,explain,active) SELECT '해마 새끼를 배의 육아낭에서 품는 쪽은 누구일까요?','["수컷 해마", "암컷 해마", "다른 물고기", "산호"]',0,'해마는 수컷의 배에 있는 육아낭에서 새끼를 품어요.',1 WHERE NOT EXISTS (SELECT 1 FROM quizquestion WHERE q='해마 새끼를 배의 육아낭에서 품는 쪽은 누구일까요?');
INSERT INTO quizquestion (q,options,answer,explain,active) SELECT '산호초의 단단한 뼈대를 만드는 것은 무엇일까요?','["산호 폴립", "바닷물의 거품", "모래알", "고래의 뼈"]',0,'작은 산호 동물인 폴립이 탄산칼슘 뼈대를 만들고, 이것이 쌓여 산호초가 돼요.',1 WHERE NOT EXISTS (SELECT 1 FROM quizquestion WHERE q='산호초의 단단한 뼈대를 만드는 것은 무엇일까요?');
INSERT INTO quizquestion (q,options,answer,explain,active) SELECT '바닷물의 밀물과 썰물에 가장 크게 관련된 힘은 무엇일까요?','["달과 태양의 중력", "배가 지나가는 힘", "물고기가 헤엄치는 힘", "바닷물의 색"]',0,'달과 태양의 중력이 바닷물의 오르내림에 영향을 줘요. 지역 지형도 밀물·썰물 시각을 바꿀 수 있어요.',1 WHERE NOT EXISTS (SELECT 1 FROM quizquestion WHERE q='바닷물의 밀물과 썰물에 가장 크게 관련된 힘은 무엇일까요?');
